 "decisions": [
  {
   "title": "One transaction per payment replaces SYNCPOINT",
   "context": "PAGOORD debits the account (PAGODEB), links PAGOMOV, rewrites the order and only then issues SYNCPOINT.",
   "decision": "PayOrder runs in a single database transaction. DebitAccount joins it when called through DebitGateway. Any business error or exception rolls back everything.",
   "consequences": "The debit, the movement registration and the order update are atomic. The legacy SYNCPOINT disappears."
  },
  {
   "title": "Pessimistic locking replaces READ ... UPDATE",
   "context": "The legacy reads ORDENES and CUENTAS with UPDATE, which holds the record until the task ends.",
   "decision": "findByKeyForUpdate and findByNumberForUpdate use SELECT ... FOR UPDATE, in the legacy order (order first, then account).",
   "consequences": "Concurrent payments of the same order or debits of the same account are serialized, as before."
  },
  {
   "title": "PAGODEB becomes a use case called in-process through DebitGateway",
   "context": "PAGOORD calls PAGODEB with LINK and a COMMAREA. PAGODEB answers with a response code (00, 10, 20, 30, 40).",
   "decision": "The debit logic lives only in the DebitAccount use case, also exposed as POST /accounts/debits. PayOrder reaches it through DebitGateway and receives the legacy code as a number. It maps 10 to ACCOUNT_INACTIVE, 20 to INSUFFICIENT_BALANCE and any other code (30, 40) to INVALID_ACCOUNT.",
   "consequences": "No duplicated rules. PAGODEB runs for real in the recorded traces, so the port has no legacy_program and is not stubbed in the replay. The effect of the debit is checked in the CUENTAS table."
  },
  {
   "title": "PAGOMOV is stubbed",
   "context": "The source of PAGOMOV is not available.",
   "decision": "MovementGateway is a port with a stub adapter. The replay uses the stubs recorded in the traces.",
   "consequences": "The real movement numbering must be implemented or integrated before going live."
  },
  {
   "title": "Amount is received in currency units",
   "context": "The legacy screen sends VALORI as 11 digits and PAGOORD converts it with NUMVAL / 100. The traces give the value as '1500.00'.",
   "decision": "The API receives amount as decimal(11,2). The comparison with the order amount is exact (scale 2, compareTo), with no rounding.",
   "consequences": "The client sends 1500.00 instead of the screen format. Any difference of one cent rejects the payment, as before."
  },
  {
   "title": "Identifiers are received as text and validated inside the use case",
   "context": "ORDENI, EMPRESAI and CUENTAI are alphanumeric on the screen and RULE-008 rejects a non-numeric or zero order number.",
   "decision": "orderNumber, companyId and accountNumber are text in PayOrder. A non-numeric or zero order number gives INVALID_ORDER_NUMBER. A non-numeric company gives ORDER_NOT_FOUND. A non-numeric account gives INVALID_ACCOUNT.",
   "consequences": "The last two are interpretations of the legacy behaviour for a non-numeric key. Screen checks (PF keys, TECLA NO VALIDA, BMS maps) are not migrated."
  },
  {
   "title": "Validation order and short circuit",
   "context": "RULE-007: validation, read, commission and debit, registration.",
   "decision": "PayOrder validates in the legacy order (order number, account type, channel, approval key), then reads the order (exists, pending, amount), calculates the commission, debits and registers. The first error ends the use case.",
   "consequences": "Only one error message is reported per request, as in the legacy."
  },
  {
   "title": "Commarea state is not persisted",
   "context": "The pseudo-conversational commarea carries state between screens. RULE-017 sets CA-ULTIMA-ORDEN.",
   "decision": "The service is stateless. The paid order number is returned as orderNumber. The menu navigation (XCTL) is the action returned by SelectMenuOption.",
   "consequences": "The client keeps any session context."
  },
  {
   "title": "Legacy status codes kept",
   "context": "Orders use 'P' (pending) and 'G' (paid). Accounts use 'A' (active) and 'I' (inactive).",
   "decision": "The values are kept in the new tables. Columns are renamed to English snake_case and FILLER is not migrated.",
   "consequences": "Data migrates without conversion."
  }
 ],
