package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.port.MovementGateway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * Stub adapter of MovementGateway (legacy program PAGOMOV, source not available).
 *
 * The target schema has no movement table, so the next movement number is derived
 * from the highest movement number already recorded in payment_orders.
 * The real movement numbering must be implemented or integrated before going live.
 */
@Repository
public class JdbcMovementGateway implements MovementGateway {

    private final JdbcTemplate jdbcTemplate;

    public JdbcMovementGateway(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public long registerMovement(Integer orderNumber) {
        Long next = jdbcTemplate.queryForObject(
                "SELECT COALESCE(MAX(movement_number), 0) + 1 FROM payment_orders",
                Long.class);
        return next == null ? 1L : next;
    }
}
